@Component
export struct AmountSurface {
 build() {
  Column() {
   Grid() { GridItem() { Text('Category picker') } }
   Row() { TextInput({ placeholder: 'Amount' }) }
    .shadow({ radius: 7 })
    .backgroundColor(Color.White)
  }
 }
}

@Component
export struct GestureLayer {
 build() {
  Stack() {}
   .onTouch(() => { this.showOverlay() })
 }
}

